(()=>{const p=document.body.dataset.page||'dashboard',nav=[['dashboard','Ringkasan','index.html'],['kamar','Kamar','kamar.html'],['booking','Booking','booking.html'],['tenant','Tenant','tenant.html'],['pembayaran','Pembayaran','pembayaran.html'],['invoice','Invoice','invoice.html'],['keluhan','Keluhan','keluhan.html'],['pengumuman','Pengumuman','pengumuman.html'],['laporan','Laporan','laporan.html'],['pengaturan','Pengaturan','pengaturan.html']];document.querySelector('[data-shell]').innerHTML=`<div class="layout"><aside class="sidebar" data-sidebar><a class="brand" href="../aeline_landing_page.html">⌂ Manzsa Residence</a><div class="tenant-card"><div class="avatar">OW</div><div><p>Owner Manzsa</p><small>Administrator</small></div></div><nav class="menu">${nav.map(x=>`<a class="${p===x[0]?'active':''}" href="${x[2]}">${x[1]}</a>`).join('')}</nav><div class="sidebar-bottom menu"><a href="../aeline_landing_page.html">Lihat Website</a><a href="../login.html">Keluar</a></div></aside><div class="content"><header class="topbar"><button class="mobile-menu" data-toggle>☰</button><div></div><strong>Owner Manzsa</strong></header><main class="page" data-content></main></div></div><div class="demo">${['normal','loading','empty','error'].map((x,i)=>`<button class="${i?'':'active'}" data-state="${x}">${x}</button>`).join('')}</div>`;document.querySelector('[data-toggle]').onclick=()=>document.querySelector('[data-sidebar]').classList.toggle('open');window.O={page:p,state:'normal',el:document.querySelector('[data-content]'),money:n=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(n),head:(t,d,a='')=>`<div class="owner-hero"><div class="head" style="margin:0"><div><h1>${t}</h1><p>${d}</p></div>${a}</div></div>`,stateBox:(t,d)=>`<div class="state"><h3>${t}</h3><p>${d}</p><button class="btn btn-dark" onclick="O.set('normal')">Coba Lagi</button></div>`,set(s){this.state=s;document.querySelectorAll('[data-state]').forEach(b=>b.classList.toggle('active',b.dataset.state===s));renderOwner()}};document.querySelectorAll('[data-state]').forEach(b=>b.onclick=()=>O.set(b.dataset.state));})();
